contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint newMinSum) public payable {
        uint beforeMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        bool revertedSetMinSum;
        c.SetMinSum(newMinSum); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            revertedSetMinSum = true;
        } else {
            revertedSetMinSum = false;
        }

        uint afterSetMinSum = c.MinSum(); if (__ESBMC_reverted()) return;

        c.Initialized(); if (__ESBMC_reverted()) return;

        uint afterInitialized = c.MinSum(); if (__ESBMC_reverted()) return;

        assert(!revertedSetMinSum && afterSetMinSum == newMinSum && afterInitialized == newMinSum);
    }

    receive() external payable {}
}

