pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {ACCURAL_DEPOSIT} from "../src/ACCURAL_DEPOSIT.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    ACCURAL_DEPOSIT c;

    function setUp() public {
        c = new ACCURAL_DEPOSIT();
    }

    function _run(uint256 newMinSum) internal {
        uint256 beforeMinSum;
        try c.MinSum() returns (uint256 __r) { beforeMinSum = __r; } catch { return; }
        bool revertedSetMinSum;
        try c.SetMinSum(newMinSum) {
            revertedSetMinSum = false;
        } catch {
            revertedSetMinSum = true;
        }
        uint256 afterSetMinSum;
        try c.MinSum() returns (uint256 __r) { afterSetMinSum = __r; } catch { return; }
        try c.Initialized() {} catch { return; }
        uint256 afterInitialized;
        try c.MinSum() returns (uint256 __r) { afterInitialized = __r; } catch { return; }
        assertTrue(!revertedSetMinSum && afterSetMinSum == newMinSum && afterInitialized == newMinSum);
    }

    function testFuzz_run(uint256 newMinSum) public {
        _run(newMinSum);
    }

    receive() external payable {}
}
